import { readFile, readdir } from 'node:fs/promises'

/** Bundle canonical CSS directly, never another framework's generated output. */
export async function bundleStyles(source) {
  const themes = (await readdir(new URL('themes/', source)))
    .filter((path) => path.endsWith('.css'))
    .sort()
  const components = (await readdir(source))
    .filter(
      (path) =>
        path.endsWith('.css') && !['base.css', 'styles.css', 'foundation.css'].includes(path),
    )
    .sort()
  const base =
    [
      '/* Generated by scripts/generate-styles.mjs. Edit foundation.css or component CSS instead. */',
      ...(
        await Promise.all(
          ['foundation.css', ...components].map((path) => readFile(new URL(path, source), 'utf8')),
        )
      ).map((style) => style.trimEnd()),
    ].join('\n\n') + '\n'
  const adapters = await Promise.all(
    themes.map((path) => readFile(new URL(`themes/${path}`, source), 'utf8')),
  )
  const styles =
    [
      '/* Generated by scripts/generate-styles.mjs. Edit foundation/component CSS or themes instead. */',
      base.trimEnd(),
      ...adapters.map((style) => style.trimEnd()),
    ].join('\n\n') + '\n'
  return { base, styles }
}
